type NodeRow = NonNullable<Awaited<ReturnType<typeof nodeRowFor>>>;

/** Put a server (whose dedicated IP has just been released) onto shared NAT. */
async function moveToNat(conn: PveClient, server: LoadedServer, nodeRow: NodeRow): Promise<{ ip: string; sshPort: number }> {
  const fresh = await db.server.findUnique({ where: { id: server.id }, select: { ipAddress: true, sshPort: true } });
  const ip = fresh?.ipAddress && fresh.ipAddress.startsWith(nodeRow.subnetPrefix) ? fresh.ipAddress : await allocateIp(server.nodeId, server.id);
  const sshPort = fresh?.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
  if (!SANDBOX && server.vmid) {
    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
      net0: `virtio,bridge=${nodeRow.bridge ?? "vmbr1"}`,
      ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow.subnetPrefix)}`,
    });
  }
  await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort, wantsDedicatedIp: false } });
  // A NAT game server needs its join port(s) forwarded; reuse rows from an
  // earlier NAT life rather than burning new public ports.
  const fam = familyOf(server);
  if (fam) {
    for (const port of joinPortsFor(fam)) {
      const already = await db.portForward.findFirst({ where: { serverId: server.id, guestPort: port.port, protocol: port.protocol }, select: { id: true } });
      if (!already) await allocateGameForward(server.nodeId, server.id, port.port, port.protocol).catch((e) => console.error(`[admin-ops] forward ${port.protocol}/${port.port} for ${server.hostname} failed`, e));
    }
  }
  return { ip, sshPort };
}

async function giveDedicated(conn: PveClient, server: LoadedServer, nodeRow: NodeRow, address: string | null, billable: boolean): Promise<string> {
  if (SANDBOX) {
    const ip = address ?? (await db.dedicatedIp.findFirst({ where: { nodeId: nodeRow.id, status: "FREE", purpose: "CUSTOMER" }, orderBy: { createdAt: "asc" } }))?.address;
    if (!ip) throw new TerminalOpError("No FREE IP in the pool (sandbox).");
    await db.$transaction([
      db.dedicatedIp.update({ where: { address: ip }, data: { status: "ASSIGNED", serverId: server.id } }),
      db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort: null, wantsDedicatedIp: billable } }),
    ]);
    return ip;
  }
  if (!server.vmid) throw new TerminalOpError(`${server.hostname} has no VM.`);
  if (address) {
    const row = await db.dedicatedIp.findFirst({ where: { address, nodeId: nodeRow.id, status: "FREE", purpose: "CUSTOMER", serverId: null }, select: { id: true } });
    if (!row) throw new TerminalOpError(`${address} is no longer FREE on ${nodeRow.name}.`);
  }
  const d = await allocateDedicatedIp(server.id, server.vmid, nodeRow.id, address ? { preferAddress: address } : undefined);
  if (!d) throw new TerminalOpError(`No FREE customer IP available on ${nodeRow.name} (or its provider API isn't configured).`);
  if (address && d.address !== address) {
    // Should be impossible with preferAddress; never silently hand out a different IP.
    await releaseDedicatedIp(server.id).catch(() => {});
    throw new TerminalOpError(`Allocator returned ${d.address} instead of ${address} — rolled back.`);
  }
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
    net0: d.virtualMac ? `virtio=${d.virtualMac},bridge=vmbr0` : `virtio,bridge=vmbr0`,
    ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
  });
  await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null, wantsDedicatedIp: billable } });
  return d.address;
}

