/** Proxmox `POST /nodes/{node}/qemu/{vmid}/config` body. */
export type VmIdentityConfig = {
  cores: number;
  memory: number;
  onboot: number;
  net0: string;
  ipconfig0: string;
};

/**
 * Raised when the `Server` row cannot describe a network the VM may legally boot
 * on. The caller must fail the restore job rather than start the VM: leaving the
 * archive's stale address in place is precisely the outcome being prevented.
 */
export class RestoreIdentityError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RestoreIdentityError";
  }
}

/**
 * The config a restored VM must be given, derived from the `Server` row.
 *
 * Mirrors what PROVISION writes in worker/index.ts (and what unsuspend rewrites)
 * so a restored machine is configured identically to a freshly provisioned one.
 */
export function restoreIdentityConfig(input: RestoreIdentityInput): VmIdentityConfig {
  const cores = Math.trunc(Number(input.plan?.cpuCores));
  const memory = Math.trunc(Number(input.plan?.ramMB));
  if (!Number.isFinite(cores) || cores < 1 || !Number.isFinite(memory) || memory < 1) {
    throw new RestoreIdentityError(
      "the server's plan has no usable cpuCores/ramMB, so the restored VM's size cannot be reasserted",
    );
  }

