477 lib/node-capacity.ts
// Per-node capacity / utilization math for the node-capacity warning feature.
//
// Plain (non-"use server") module — safe to import from admin server components
// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
// off it). No mutations here; the alert lifecycle lives in the worker so this
// file stays a pure-ish reader other surfaces can share, exactly like the
// read-only helpers in lib/monitoring.ts.
//
// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
// new work when they do, so both are reduced to the same shape: a list of
// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
//
// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
//   - allocation: what the DB has COMMITTED to the node (sum of every server's
//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
//     provision fail — a node can be 100% committed while barely warm.
//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
//     which is what makes a node DEGRADE.
// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
// which is the honest "add a node before this bites" signal the feature exists
// to give.

import { db } from "./db";
import type { NodeProvider } from "@prisma/client";
import { nodeRamUsage, nodeStorageUsage, backupSummary, BACKUP_STALE_MS, type NodeRam, type StorageUsage } from "./monitoring";
import { effectiveDiskGB, baseDiskGBFor } from "./extra-disk";
import { getSettingInt } from "./settings";
import { nodeTemplateVmids, nodesWithTemplate } from "./node-templates";
import { logError } from "./log";
import { SANDBOX } from "./sandbox";
// severityFor/capBarColor/CapSeverity/NodeThresholds live in capacity-severity.ts
// (a dependency-free, client-safe module) and are re-exported here unchanged —
// see that file's doc comment for why they were split out.
import { severityFor, capBarColor, isGenuineSeverityChange, type CapSeverity, type NodeThresholds } from "./capacity-severity";

export { severityFor, capBarColor, isGenuineSeverityChange, type CapSeverity, type NodeThresholds };

const MB = 1024 * 1024;
const GB = 1024 ** 3;

export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS" | "BACKUP";
export type NodeKind = "PROXMOX" | "HOSTING";

export const NODE_CAP_DEFAULT_WARN = 80;
export const NODE_CAP_DEFAULT_CRIT = 90;

/**
 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
 * points BELOW the WARN threshold. Without the gap a node parked right on the
 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
 * churn. Env-overridable for tuning without a redeploy.
 */
export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);

/**
 * A persistent (unchanged-severity) condition re-notifies at most once per this
 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
 * immediately regardless of the cooldown.
 */
export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);

/**
 * Every server status EXCEPT DELETING still holds committed capacity on its node
 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
 * matches the exclusion the existing scheduler and infra pages already use
 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
 * scheduleNode commits against.
 */
const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
/** Hosting-account statuses that still occupy a slot / quota on their node. */
const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;

/**
 * Resolve the admin-configured thresholds, clamped so they are always usable:
 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
 * the amber band unreachable and every warn instantly read critical).
 */
export async function nodeThresholds(): Promise<NodeThresholds> {
  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
  if (critPct < warnPct) critPct = warnPct;
  return { warnPct, critPct };
}


/** The percent below which an OPEN alert is allowed to auto-resolve. */
export function resolveFloor(t: NodeThresholds): number {
  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
}

export type DimUtil = {
  dimension: CapDimension;
  /** The value thresholded — the worse of allocation and real usage. */
  pct: number;
  /** DB-committed percent (null when the dimension has no allocation basis). */
  allocPct: number | null;
  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
  realPct: number | null;
  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
  detail: string;
  /** `allocPct`'s own absolute breakdown alone, e.g. "48 / 56 GB" — for UIs that
   *  render committed and used as two separate rows instead of one combined
   *  line. Null exactly when `allocPct` is null. */
  allocDetail: string | null;
  /** `realPct`'s own absolute breakdown alone, e.g. "34 GB used" — same
   *  pairing as `allocDetail`, null exactly when `realPct` is null. */
  realDetail: string | null;
};

export type NodeUtil = {
  kind: NodeKind;
  id: string;
  name: string;
  enabled: boolean;
  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
  reachable: boolean;
  dims: DimUtil[];
  /** Worst dimension percent across `dims` (0 when there are none). */
  worstPct: number;
  severity: CapSeverity;
};

function pct(part: number, whole: number): number | null {
  if (!(whole > 0)) return null;
  return (part / whole) * 100;
}

/** Combine allocation + real into the thresholded value (worse of the two). */
function worse(allocPct: number | null, realPct: number | null): number {
  return Math.max(allocPct ?? 0, realPct ?? 0);
}

function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
  return { worstPct, severity: severityFor(worstPct, t) };
}

// ---------------------------------------------------------------------------
// Proxmox compute nodes
// ---------------------------------------------------------------------------

/**
 * Utilization for every registered Proxmox node.
 *
 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
 * each live server's `plan.ramMB`; real usage from the node status endpoint when
 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
 * (physical thread count / storage pool size), so on an unreachable node they are
 * simply omitted rather than guessed — `reachable:false` tells the UI and the
 * sweep to treat their absence as "unknown", never as "recovered".
 */
export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
  const nodes = await db.node.findMany({
    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
    include: {
      servers: {
        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
        select: {
          extraDiskGB: true,
          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
          gamePlan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
        },
      },
    },
  });

  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
  let ramRows: NodeRam[] = [];
  let storageRows: StorageUsage[] = [];
  let backupRows: Awaited<ReturnType<typeof backupSummary>> = [];
  try {
    ramRows = await nodeRamUsage();
  } catch {
    /* leave empty — every node reads unreachable */
  }
  try {
    storageRows = await nodeStorageUsage();
  } catch {
    /* leave empty */
  }
  try {
    backupRows = await backupSummary();
  } catch {
    /* leave empty — BACKUP dim simply omitted below, same as an unreachable CPU/DISK */
  }
  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
  const backupByNode = new Map(backupRows.map((b) => [b.node, b]));

  return nodes.map((n) => {
    // A game server's real commitment is its game plan's, not the (larger)
    // base VPS plan it rides on — see lib/extra-disk.ts's baseDiskGBFor.
    const committedRamMB = n.servers.reduce((s, sv) => s + (sv.gamePlan?.ramMB ?? sv.plan.ramMB), 0);
    const committedDiskGB = n.servers.reduce(
      (s, sv) => s + effectiveDiskGB(baseDiskGBFor(sv), sv.extraDiskGB),
      0,
    );
    const committedVcpu = n.servers.reduce((s, sv) => s + (sv.gamePlan?.cpuCores ?? sv.plan.cpuCores), 0);

    const real = ramByNode.get(n.name);
    const reachable = !!real?.reachable;
    // The node's own VM-disk pool (storageNvme) is the disk denominator.
    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);

    const dims: DimUtil[] = [];

    // RAM — allocation always available; real when reachable.
    {
      const allocPct = pct(committedRamMB, n.capacityRamMB);
      const realPct = reachable && real ? real.ratio * 100 : null;
      const p = worse(allocPct, realPct);
      const allocDetail = `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB`;
      const realDetail = realPct !== null && real ? `${(real.used / GB).toFixed(0)} GB used` : null;
      const parts = [`${allocDetail} committed`];
      if (realDetail) parts.push(realDetail);
      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
    }

    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
    // allocation ratio is context, not an alarm). Only present when reachable.
    if (reachable && real) {
      const realPct = real.cpu * 100;
      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
      const allocDetail = allocPct !== null ? `${committedVcpu} vCPU / ${real.cores} threads` : null;
      const realDetail = `${Math.round(realPct)}% used`;
      const parts = [realDetail];
      if (allocDetail) parts.push(`${allocDetail} (${Math.round(allocPct!)}% committed)`);
      // CPU is thresholded on REAL load only; overcommit alloc is informational.
      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
    }

    // DISK — needs the pool size from Proxmox. Allocation = committed effective
    // disk vs pool total; real = pool used vs pool total. Worse of the two.
    if (vmStorage?.reachable && vmStorage.total > 0) {
      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
      const realPct = vmStorage.ratio * 100;
      const p = worse(allocPct, realPct);
      const allocDetail = `${committedDiskGB} GB / ${(vmStorage.total / GB).toFixed(0)} GB`;
      const realDetail = `${(vmStorage.ratio * (vmStorage.total / GB)).toFixed(0)} GB used`;
      dims.push({
        dimension: "DISK",
        pct: p,
        allocPct,
        realPct,
        detail: `${allocDetail} committed · ${Math.round(realPct)}% used`,
        allocDetail,
        realDetail,
      });
    }

    // BACKUP — no allocation concept; thresholded on how stale the newest backup
    // is versus BACKUP_STALE_MS (so it crosses WARN/CRITICAL at 80%/90% of the
    // staleness window, reusing the same admin-configured thresholds as the other
    // dimensions). A node whose storage answers but shows zero backups EVER is
    // treated as maximally stale (100%) — that is precisely the "silently-broken
    // schedule on a node nobody's watching" case this dimension exists to catch.
    // Omitted entirely when the storage itself is unreachable — unknown, not OK.
    {
      const b = backupByNode.get(n.name);
      if (b?.reachable) {
        const ageMs = b.newestCtime !== null ? Date.now() - b.newestCtime * 1000 : null;
        const p = ageMs === null ? 100 : Math.min(100, (ageMs / BACKUP_STALE_MS) * 100);
        const detail =
          ageMs === null
            ? `No backups found on this node's storage (${b.count} on disk).`
            : `Newest backup ${Math.round(ageMs / 3_600_000)}h old · ${b.count} on disk (stale past ${Math.round(BACKUP_STALE_MS / 3_600_000)}h).`;
        dims.push({ dimension: "BACKUP", pct: p, allocPct: null, realPct: p, detail, allocDetail: null, realDetail: detail });
      }
    }

    return {
      kind: "PROXMOX" as const,
      id: n.id,
      name: n.name,
      enabled: n.enabled,
      reachable,
      dims,
      ...rollup(dims, t),
    };
  });
}

// ---------------------------------------------------------------------------
// Shared-hosting nodes
// ---------------------------------------------------------------------------

/**
 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
 * quotas live in our own tables), so it is always reachable:
 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
 *     scheduler cap; the next account is refused once it's full.
 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
 */
export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });

  return Promise.all(
    nodes.map(async (n) => {
      const [count, agg] = await Promise.all([
        db.hostingAccount.count({
          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
        }),
        db.hostingAccount.aggregate({
          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
          _sum: { diskQuotaMB: true, diskUsedMB: true },
        }),
      ]);

      const totalDiskMB = n.diskTotalGB * 1024;
      const quotaMB = agg._sum.diskQuotaMB ?? 0;
      const usedMB = agg._sum.diskUsedMB ?? 0;

      const dims: DimUtil[] = [];

      // ACCOUNTS
      {
        const allocPct = pct(count, n.maxAccounts);
        const p = allocPct ?? 0;
        const allocDetail = `${count} / ${n.maxAccounts} accounts`;
        dims.push({
          dimension: "ACCOUNTS",
          pct: p,
          allocPct,
          realPct: null,
          detail: allocDetail,
          allocDetail,
          realDetail: null,
        });
      }

      // DISK
      {
        const allocPct = pct(quotaMB, totalDiskMB);
        const realPct = pct(usedMB, totalDiskMB);
        const p = worse(allocPct, realPct);
        const allocDetail = `${(quotaMB / 1024).toFixed(0)} GB / ${n.diskTotalGB} GB`;
        const realDetail = realPct !== null ? `${(usedMB / 1024).toFixed(0)} GB used` : null;
        const parts = [`${allocDetail} quota`];
        if (realDetail) parts.push(realDetail);
        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
      }

      return {
        kind: "HOSTING" as const,
        id: n.id,
        name: n.name,
        enabled: n.enabled,
        reachable: true,
        dims,
        ...rollup(dims, t),
      };
    }),
  );
}

/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
  const thresholds = await nodeThresholds();
  const [proxmox, hosting] = await Promise.all([
    proxmoxNodeUtil(thresholds),
    hostingNodeUtil(thresholds),
  ]);
  return { thresholds, nodes: [...proxmox, ...hosting] };
}

/**
 * Pick the best Proxmox node for a new server of `planRamMB`, when the
 * customer didn't choose a location explicitly. Bin-packs onto whichever
 * ONLINE, enabled node has the most free RAM after projecting this VM onto
 * it, staying under the CRITICAL threshold when any node can (falling back to
 * least-bad if every node is already critical).
 *
 * THIRD copy, consolidated here. This existed as two near-identical private
 * copies — `lib/order.ts` (VPS orders) and `lib/actions-nxcloud.ts` (NxCloud
 * orders) — and `lib/game-order.ts`'s game-server order path never called
 * either one at all: it creates its `Server` row with no `nodeId`, so every
 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
 * RAM and 200% committed CPU while other nodes are comparatively idle, and
 * every game server in production has `nodeId: null`. Fixed by giving
 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
 * rather than writing a fourth copy or leaving it unscheduled.
 */
export async function scheduleNode(
  planRamMB: number,
  // templateVmid: the Proxmox template this order clones (OsTemplate.baseVmid
  // ?? vmid). When given, nodes that do not have it are never chosen — see
  // lib/node-templates.ts for the incident. Omitted = previous behaviour.
  opts?: { provider?: NodeProvider; region?: string; templateVmid?: number | null },
) {
  // Customer picks a REGION (e.g. "Singapore"), never a specific physical
  // node — multiple nodes can share one region (primary + node-3 are both
  // OVH/sgp1), and forcing a customer's choice onto one specific node meant
  // that node alone ever took new signups for that region, regardless of its
  // actual load relative to its sibling in the same region. Filtering here
  // (rather than a separate function) keeps this the single place "which
  // node wins" is decided, with or without a region constraint.
  const nodes = await db.node.findMany({
    where: {
      enabled: true,
      status: "ONLINE",
      // Distinct from `enabled` — a node can stay visible/online with its
      // existing servers running and still be excluded from taking NEW ones
      // (the admin Infrastructure page's per-node toggle).
      acceptsProvisions: true,
      ...(opts?.region ? { region: opts.region } : {}),
      ...(opts?.provider ? { provider: opts.provider } : {}),
    },
  });
  if (nodes.length === 0) return null;
  let candidates = nodes;
  if (opts?.templateVmid && !SANDBOX) {
    const tv = opts.templateVmid;
    const lookup = new Map(await Promise.all(nodes.map(async (n) => [n.id, await nodeTemplateVmids(n)] as const)));
    const { ok, missing } = nodesWithTemplate(nodes, tv, lookup);
    if (missing.length > 0) {
      logError("node-scheduler", new Error(`template ${tv} missing on ${missing.map((m) => m.name).join(", ")}`), {
        templateVmid: tv,
        excluded: missing.map((m) => m.name),
        note: "these nodes were skipped for this order; copy the template to them (scripts/onboard-node.sh) to restore capacity",
      });
    }
    if (ok.length === 0) return null;
    candidates = ok;
  }
  const loads = await Promise.all(
    candidates.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
      });
      // A game server's real commitment is its game plan's ram, not the
      // (larger) base VPS plan it rides on — overstating every game server's
      // load here skews which node the scheduler picks for the NEXT one.
      const used = agg.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
      // Commitment AFTER this VM lands — that's what decides whether placing
      // here tips the node critical.
      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
      return { node: n, free: n.capacityRamMB - used, projectedPct };
    }),
  );
  const { critPct } = await nodeThresholds();
  const roomy = loads.filter((l) => l.projectedPct < critPct);
  const pool = roomy.length > 0 ? roomy : loads;
  pool.sort((a, b) => b.free - a.free);
  return pool[0].node;
}

/**
 * True only when EVERY enabled compute node is at/above its RAM warn
 * threshold — the signal for the public "reserve your server now" banner.
 * A single loaded node must NOT trigger this: `scheduleNode()` can still
 * place a new order on a roomier node, so warning the public the moment
 * only one host is busy would be a false "we're out of capacity" claim.
 * Deliberately internals-free for the caller — no node names, no percentages,
 * no "Host"/"committed RAM" — this is a customer-facing scarcity signal, not
 * an ops metric (see lib/capacity.ts's ops-facing capacitySnapshot for that).
 */
export async function fleetNearCapacity(): Promise<boolean> {
  const t = await nodeThresholds();
  const nodes = (await proxmoxNodeUtil(t)).filter((n) => n.enabled);
  if (nodes.length === 0) return false;
  return nodes.every((n) => {
    const ram = n.dims.find((d) => d.dimension === "RAM");
    return (ram?.pct ?? 0) >= t.warnPct;
  });
}

export { MB, GB };

