/**
 * VM memory policy: how much of a customer VM's RAM Proxmox may take back
 * (ballooning), plus the pure math for the node RAM guard that keeps pinned
 * memory from over-committing a node. Pure on purpose (no db, no network):
 * the worker, the scheduler (lib/node-ram-guard.ts), the remediation script
 * (scripts/pin-vm-memory.ts) and the tests all share it.
 *
 * WHY (2026-10-01). Since 2026-09-14 every VM was created with
 * `balloon = max(1024, 50% of plan RAM)`. pvestatd auto-ballooning shrinks a
 * guest toward that floor whenever its node sits above ~80% RAM. On node-4
 * (89% used) a customer's 4 GB Valheim VM sat at ~1.8 GB for days while
 * running 23 mods ("1.82 GiB is not enough memory" in the game log). A live
 * `balloon 4096` monitor command was undone by pvestatd within seconds,
 * because the config floor still allowed the shrink. A customer must get the
 * RAM they pay for, so customer VMs now get a floor EQUAL to their plan RAM.
 *
 * POLICIES (env NXEON_BALLOON_POLICY):
 *   pin   (default) balloon = memory. Proxmox's documented "fixed memory"
 *         mode: the virtio-balloon device stays (guest memory stats, and on
 *         recent qemu-server free-page reporting, which hands pages a guest
 *         frees back to the host), but pvestatd can never shrink the guest,
 *         because its minimum equals its maximum. Changing an existing VM to
 *         this is LIVE: the device stays enabled, so Proxmox applies the new
 *         minimum at once and pvestatd's next pass raises the target to the
 *         full size. No reboot.
 *   off   balloon = 0. Removes the balloon device. Same guarantee, but no
 *         memory stats from the device, no free-page reporting, and turning
 *         the device off on an existing VM is NOT hotpluggable: the change
 *         sits in the pending config until a COLD stop + start.
 *   floor the old 50%/min-1024 floor. Escape hatch only: it is the behaviour
 *         that caused the incident. Use it if a node is in a RAM emergency
 *         and the owner accepts squeezing customers to avoid an OOM kill.
 *
 * WHY pin, not off, by default: both guarantee the RAM. pin is applied live
 * to existing VMs (no customer downtime), keeps the device so a future
 * emergency can still be handled live, and free-page reporting keeps host RSS
 * closer to what guests really use. That last point matters: pinning removes
 * the host's ability to reclaim from guests, so the node RAM guard below is
 * what keeps a node from being over-committed instead.
 *
 * The free-Minecraft shared host (freemc-host, node-2 vmid 100) is not a
 * `Server` row and is not created by the worker; it was pinned the same way
 * (balloon = memory) by scripts/freemc/rollout/01-pin-guest-memory.sh. This
 * module does not change it.
 */

export type BalloonPolicy = "pin" | "off" | "floor";

export const BALLOON_POLICIES: readonly BalloonPolicy[] = ["pin", "off", "floor"];

/** Resolve the policy from env. Unknown/empty values fall back to `pin`. */
export function balloonPolicy(env: Record<string, string | undefined> = process.env): BalloonPolicy {
  const v = (env.NXEON_BALLOON_POLICY ?? "").trim().toLowerCase();
  return (BALLOON_POLICIES as readonly string[]).includes(v) ? (v as BalloonPolicy) : "pin";
}

/** The legacy floor (pre-2026-10-01): 50% of RAM, min 1024, never above RAM. */
export function legacyBalloonFloorMB(memoryMB: number): number {
  return Math.min(memoryMB, Math.max(1024, Math.round(memoryMB * 0.5)));
}

/**
 * The `balloon` value (MB) to write into a VM config for `memoryMB` of RAM.
 * pin -> memoryMB, off -> 0, floor -> legacy floor.
 */
export function balloonFor(memoryMB: number, policy: BalloonPolicy = balloonPolicy()): number {
  const mem = Math.trunc(Number(memoryMB));
  if (!Number.isFinite(mem) || mem < 1) throw new Error(`balloonFor: invalid memory ${memoryMB}`);
  if (policy === "off") return 0;
  if (policy === "floor") return legacyBalloonFloorMB(mem);
  return mem;
}

/** `{ memory, balloon }` pair for a Proxmox config POST. */
export function memoryConfig(memoryMB: number, policy: BalloonPolicy = balloonPolicy()): { memory: number; balloon: number } {
  return { memory: Math.trunc(memoryMB), balloon: balloonFor(memoryMB, policy) };
}

function num(v: unknown): number | null {
  if (v === undefined || v === null || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

/**
 * The RAM (MB) Proxmox guarantees a VM: the lowest it may balloon it to.
 *   balloon unset -> device on, minimum defaults to memory -> memory
 *   balloon 0     -> no device -> memory
 *   otherwise     -> min(balloon, memory)
 */
export function guaranteedMB(memoryMB: unknown, balloonMB: unknown): number {
  const mem = num(memoryMB) ?? 0;
  const b = num(balloonMB);
  if (b === null || b === 0) return mem;
  return Math.min(b, mem);
}

export type VmMemoryState = {
  /** `memory` from the VM config (MB). */
  memoryMB: number;
  /** `balloon` from the CURRENT (running) config, null if unset. */
  balloonMB: number | null;
  /** `balloon` from the pending config, when a change is waiting for a cold restart. */
  pendingBalloonMB?: number | null;
  /** What the customer paid for (gamePlan.ramMB ?? plan.ramMB). */
  planRamMB: number;
};

export type PinVerdict =
  | { action: "ok"; note: string }
  | { action: "pending-restart"; note: string }
  | { action: "pin"; note: string }
  | { action: "memory-below-plan"; note: string };

/**
 * What the remediation script should do with one VM.
 *   ok                 floor already >= plan RAM.
 *   pending-restart    a balloon:0 is already pending; only a cold restart is missing.
 *   pin                floor < plan RAM: set balloon.
 *   memory-below-plan  `memory` itself is below the plan: a sizing problem
 *                      (resize territory), reported, never touched here.
 */
export function pinVerdict(s: VmMemoryState): PinVerdict {
  if (s.memoryMB < s.planRamMB) {
    return { action: "memory-below-plan", note: `memory ${s.memoryMB} MB < plan ${s.planRamMB} MB (sizing issue, not ballooning)` };
  }
  const floor = guaranteedMB(s.memoryMB, s.balloonMB);
  if (floor >= s.planRamMB) return { action: "ok", note: `floor ${floor} MB >= plan ${s.planRamMB} MB` };
  const pend = s.pendingBalloonMB;
  if (pend !== undefined && pend !== null && guaranteedMB(s.memoryMB, pend) >= s.planRamMB) {
    return { action: "pending-restart", note: `balloon ${pend} already pending; needs a cold stop+start` };
  }
  return { action: "pin", note: `floor ${floor} MB < plan ${s.planRamMB} MB` };
}

/**
 * Whether a balloon change from `fromMB` to `toMB` is applied live by Proxmox.
 * Enabling/disabling the device (0 <-> non-zero) is not hotpluggable and waits
 * in pending config for a cold stop+start. Changing the minimum while the
 * device stays on is applied at once.
 */
export function balloonChangeIsLive(fromMB: number | null, toMB: number): boolean {
  const fromOn = fromMB === null || fromMB !== 0;
  const toOn = toMB !== 0;
  return fromOn === toOn;
}

// ---------------------------------------------------------------------------
// Node RAM guard (pure math). The reader lives in lib/node-ram-guard.ts.
// ---------------------------------------------------------------------------

export type RamGuardMode = "enforce" | "warn" | "off";

export function ramGuardMode(env: Record<string, string | undefined> = process.env): RamGuardMode {
  const v = (env.NXEON_RAM_GUARD ?? "").trim().toLowerCase();
  return v === "warn" || v === "off" ? v : "enforce";
}

export type RamGuardConfig = {
  /** RAM kept for the host itself: ZFS ARC (capped at 8 GB on the primary) + host OS/pve daemons. */
  hostReserveMB: number;
  /** Max share of (total - reserve) that guaranteed (pinned + floors) VM RAM may reach. */
  maxGuaranteedRatio: number;
  /** Max share of physical RAM that real used + the new VM may reach. */
  maxRealRatio: number;
};

export function ramGuardConfig(env: Record<string, string | undefined> = process.env): RamGuardConfig {
  const n = (k: string, d: number, lo: number, hi: number) => {
    const v = Number(env[k]);
    return Number.isFinite(v) && v >= lo && v <= hi ? v : d;
  };
  return {
    hostReserveMB: n("NXEON_HOST_RESERVE_MB", 10240, 0, 1_048_576),
    maxGuaranteedRatio: n("NXEON_PINNED_RAM_MAX_RATIO", 0.95, 0.1, 1),
    maxRealRatio: n("NXEON_REAL_RAM_MAX_RATIO", 0.9, 0.1, 1),
  };
}

export type ListedVm = {
  vmid: number;
  status: string;
  template?: boolean;
  /** Config `memory` (MB). */
  memoryMB: number;
  /** Config `balloon` (MB, current), null when unset. */
  balloonMB: number | null;
};

export type NodeRamSnapshot = {
  /** Physical RAM (MB), from /nodes/<n>/status memory.total. */
  totalMB: number;
  /** Real used (MB), memory.used (MemTotal - MemAvailable; includes ZFS ARC). */
  usedMB: number;
  /** Sum of guaranteed RAM of every RUNNING non-template VM on the node (all VMs, not only Nxeon customers). */
  guaranteedMB: number;
  /** Sum of `memory` of every running VM (the ceiling they may grow to). */
  ceilingMB: number;
  runningVms: number;
};

/** Reduce a node's VM list to the guard's guaranteed/ceiling totals. */
export function summarizeVms(vms: ListedVm[]): { guaranteedMB: number; ceilingMB: number; runningVms: number } {
  let g = 0;
  let c = 0;
  let r = 0;
  for (const v of vms) {
    if (v.template || v.status !== "running") continue;
    g += guaranteedMB(v.memoryMB, v.balloonMB);
    c += v.memoryMB;
    r += 1;
  }
  return { guaranteedMB: g, ceilingMB: c, runningVms: r };
}

export type RamGuardVerdict = {
  ok: boolean;
  reason: string;
  /** Guaranteed RAM after the new VM, as % of (total - reserve). */
  projectedGuaranteedPct: number;
  /** Real used + new VM, as % of total. */
  projectedRealPct: number;
};

/**
 * Can a node take one more VM that pins `newVmMB`? Two independent checks,
 * both must pass:
 *  1. guaranteed + new <= (total - hostReserve) * maxGuaranteedRatio.
 *     Every pinned VM can always claim its full RAM; this keeps the sum of
 *     those claims below what the host can physically hand out after its own
 *     reserve (ZFS ARC cap + host). This is what makes pinning safe.
 *  2. used + new <= total * maxRealRatio. What is really in use right now
 *     (ARC included) must leave room; node-4 at 89% fails this for any VM.
 * The DB-committed check in scheduleNode (sum of plan RAM of every
 * non-deleting server vs Node.capacityRamMB, < CRITICAL) still runs too: it
 * covers STOPPED customer VMs, which this live view cannot see as claims.
 */
export function ramGuardVerdict(snap: NodeRamSnapshot, newVmMB: number, cfg: RamGuardConfig): RamGuardVerdict {
  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
  const projG = snap.guaranteedMB + newVmMB;
  const projR = snap.usedMB + newVmMB;
  const gPct = budget > 0 ? (projG / budget) * 100 : Infinity;
  const rPct = snap.totalMB > 0 ? (projR / snap.totalMB) * 100 : Infinity;
  const gLimit = budget * cfg.maxGuaranteedRatio;
  const rLimit = snap.totalMB * cfg.maxRealRatio;
  const problems: string[] = [];
  if (!(snap.totalMB > 0)) problems.push("node reported no RAM total");
  else {
    if (projG > gLimit) {
      problems.push(
        `guaranteed VM RAM would be ${Math.round(projG)} MB > ${Math.round(gLimit)} MB ` +
          `(${Math.round(cfg.maxGuaranteedRatio * 100)}% of ${snap.totalMB} MB minus ${cfg.hostReserveMB} MB host reserve)`,
      );
    }
    if (projR > rLimit) {
      problems.push(
        `real used would be ${Math.round(projR)} MB > ${Math.round(rLimit)} MB (${Math.round(cfg.maxRealRatio * 100)}% of ${snap.totalMB} MB)`,
      );
    }
  }
  return {
    ok: problems.length === 0,
    reason: problems.length ? problems.join("; ") : "ok",
    projectedGuaranteedPct: gPct,
    projectedRealPct: rPct,
  };
}

/** Headroom (MB) a node has for more pinned RAM under both checks (may be negative). */
export function pinnedHeadroomMB(snap: NodeRamSnapshot, cfg: RamGuardConfig): number {
  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
  const g = budget * cfg.maxGuaranteedRatio - snap.guaranteedMB;
  const r = snap.totalMB * cfg.maxRealRatio - snap.usedMB;
  return Math.floor(Math.min(g, r));
}

