    const v = Number(env[k]);
    return Number.isFinite(v) && v >= lo && v <= hi ? v : d;
  };
  return {
    hostReserveMB: n("NXEON_HOST_RESERVE_MB", 10240, 0, 1_048_576),
    maxGuaranteedRatio: n("NXEON_PINNED_RAM_MAX_RATIO", 0.95, 0.1, 1),
    maxRealRatio: n("NXEON_REAL_RAM_MAX_RATIO", 0.9, 0.1, 1),
  };
}

export type ListedVm = {
  vmid: number;
  status: string;
  template?: boolean;
  /** Config `memory` (MB). */
  memoryMB: number;
  /** Config `balloon` (MB, current), null when unset. */
  balloonMB: number | null;
};

export type NodeRamSnapshot = {
  /** Physical RAM (MB), from /nodes/<n>/status memory.total. */
  totalMB: number;
  /** Real used (MB), memory.used (MemTotal - MemAvailable; includes ZFS ARC). */
  usedMB: number;
  /** Sum of guaranteed RAM of every RUNNING non-template VM on the node (all VMs, not only Nxeon customers). */
  guaranteedMB: number;
  /** Sum of `memory` of every running VM (the ceiling they may grow to). */
  ceilingMB: number;
  runningVms: number;
};

/** Reduce a node's VM list to the guard's guaranteed/ceiling totals. */
export function summarizeVms(vms: ListedVm[]): { guaranteedMB: number; ceilingMB: number; runningVms: number } {
  let g = 0;
  let c = 0;
  let r = 0;
  for (const v of vms) {
    if (v.template || v.status !== "running") continue;
    g += guaranteedMB(v.memoryMB, v.balloonMB);
    c += v.memoryMB;
    r += 1;
  }
  return { guaranteedMB: g, ceilingMB: c, runningVms: r };
}

export type RamGuardVerdict = {
  ok: boolean;
  reason: string;
  /** Guaranteed RAM after the new VM, as % of (total - reserve). */
  projectedGuaranteedPct: number;
  /** Real used + new VM, as % of total. */
  projectedRealPct: number;
};

/**
 * Can a node take one more VM that pins `newVmMB`? Two independent checks,
 * both must pass:
 *  1. guaranteed + new <= (total - hostReserve) * maxGuaranteedRatio.
 *     Every pinned VM can always claim its full RAM; this keeps the sum of
 *     those claims below what the host can physically hand out after its own
 *     reserve (ZFS ARC cap + host). This is what makes pinning safe.
 *  2. used + new <= total * maxRealRatio. What is really in use right now
 *     (ARC included) must leave room; node-4 at 89% fails this for any VM.
 * The DB-committed check in scheduleNode (sum of plan RAM of every
 * non-deleting server vs Node.capacityRamMB, < CRITICAL) still runs too: it
 * covers STOPPED customer VMs, which this live view cannot see as claims.
 */
export function ramGuardVerdict(snap: NodeRamSnapshot, newVmMB: number, cfg: RamGuardConfig): RamGuardVerdict {
  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
  const projG = snap.guaranteedMB + newVmMB;
  const projR = snap.usedMB + newVmMB;
  const gPct = budget > 0 ? (projG / budget) * 100 : Infinity;
  const rPct = snap.totalMB > 0 ? (projR / snap.totalMB) * 100 : Infinity;
  const gLimit = budget * cfg.maxGuaranteedRatio;
  const rLimit = snap.totalMB * cfg.maxRealRatio;
  const problems: string[] = [];
  if (!(snap.totalMB > 0)) problems.push("node reported no RAM total");
  else {
    if (projG > gLimit) {
      problems.push(
        `guaranteed VM RAM would be ${Math.round(projG)} MB > ${Math.round(gLimit)} MB ` +
          `(${Math.round(cfg.maxGuaranteedRatio * 100)}% of ${snap.totalMB} MB minus ${cfg.hostReserveMB} MB host reserve)`,
      );
    }
    if (projR > rLimit) {
      problems.push(
        `real used would be ${Math.round(projR)} MB > ${Math.round(rLimit)} MB (${Math.round(cfg.maxRealRatio * 100)}% of ${snap.totalMB} MB)`,
      );
    }
  }
  return {
    ok: problems.length === 0,
    reason: problems.length ? problems.join("; ") : "ok",
    projectedGuaranteedPct: gPct,
    projectedRealPct: rPct,
  };
}

/** Headroom (MB) a node has for more pinned RAM under both checks (may be negative). */
export function pinnedHeadroomMB(snap: NodeRamSnapshot, cfg: RamGuardConfig): number {
  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
  const g = budget * cfg.maxGuaranteedRatio - snap.guaranteedMB;
  const r = snap.totalMB * cfg.maxRealRatio - snap.usedMB;
  return Math.floor(Math.min(g, r));
}

