/**
 * Live node RAM guard for scheduling (read-only Proxmox reads).
 *
 * Customer VMs are now pinned (lib/vm-memory-policy.ts): Proxmox can no
 * longer balloon them down when a node gets busy. That removes the host's
 * pressure valve, so a node must not be handed more pinned RAM than it can
 * physically back. scheduleNode() asks this module, per candidate node:
 * "sum of guaranteed RAM of every running VM (customer AND platform VMs,
 * read from the real configs) + this new VM" vs physical RAM minus the host
 * reserve, and "real used + this new VM" vs physical RAM. See
 * ramGuardVerdict() for the exact rule and the env knobs.
 *
 * Reads: GET /nodes/<n>/status, GET /nodes/<n>/qemu, and
 * GET /nodes/<n>/qemu/<vmid>/config?current=1 per running VM. Cached per node
 * for SNAPSHOT_TTL_MS; each read is time-boxed so an unresponsive node
 * cannot stall checkout. A node whose snapshot cannot be read is reported as
 * `unknown` and treated as NOT passing in enforce mode (fail closed, same
 * convention as lib/node-templates.ts).
 */
import { pveFor } from "./proxmox";
import {
  summarizeVms,
  ramGuardVerdict,
  ramGuardConfig,
  type ListedVm,
  type NodeRamSnapshot,
  type RamGuardVerdict,
} from "./vm-memory-policy";

export const SNAPSHOT_TTL_MS = 60_000;
const READ_TIMEOUT_MS = 8_000;

type NodeLike = { id: string; name: string; apiUrl: string; pveNode: string; tokenId: string; tokenSecret: string };

const cache = new Map<string, { at: number; snap: NodeRamSnapshot | null }>();

function timeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, rej) => setTimeout(() => rej(new Error(`${what} timed out after ${ms}ms`)), ms)),
  ]);
}

const MB = 1024 * 1024;

/** Read a node's live RAM snapshot (uncached). Throws on any read failure. */
export async function readNodeRamSnapshot(node: NodeLike): Promise<{ snap: NodeRamSnapshot; vms: (ListedVm & { name?: string })[] }> {
  const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
  const [status, list] = await Promise.all([
    timeout(conn.get(`/nodes/${node.pveNode}/status`), READ_TIMEOUT_MS, "node status"),
    timeout(conn.get(`/nodes/${node.pveNode}/qemu`), READ_TIMEOUT_MS, "vm list"),
  ]);
  const rows: any[] = Array.isArray(list) ? list : [];
  const vms = await Promise.all(
    rows.map(async (r) => {
      const vmid = Number(r?.vmid);
      const template = String(r?.template ?? "") === "1";
      const status = String(r?.status ?? "");
      const listedMB = Math.round(Number(r?.maxmem ?? 0) / MB);
      if (template || status !== "running") {
        return { vmid, status, template, memoryMB: listedMB, balloonMB: null, name: r?.name } as ListedVm & { name?: string };
      }
      // current=1: the values the RUNNING VM has, not a pending change.
      const cfg = await timeout(
        conn.get(`/nodes/${node.pveNode}/qemu/${vmid}/config`, { current: 1 }),
        READ_TIMEOUT_MS,
        `config ${vmid}`,
      );
      const memoryMB = Number(cfg?.memory ?? listedMB) || listedMB;
      const b = cfg?.balloon;
      const balloonMB = b === undefined || b === null || b === "" ? null : Number(b);
      return { vmid, status, template, memoryMB, balloonMB, name: r?.name } as ListedVm & { name?: string };
    }),
  );
  const totals = summarizeVms(vms);
  const snap: NodeRamSnapshot = {
    totalMB: Math.round(Number(status?.memory?.total ?? 0) / MB),
    usedMB: Math.round(Number(status?.memory?.used ?? 0) / MB),
    ...totals,
  };
  return { snap, vms };
}

/** Cached snapshot, or null when the node could not be read. */
export async function nodeRamSnapshot(node: NodeLike, now = Date.now()): Promise<NodeRamSnapshot | null> {
  const hit = cache.get(node.id);
  if (hit && now - hit.at < SNAPSHOT_TTL_MS) return hit.snap;
  let snap: NodeRamSnapshot | null = null;
  try {
    snap = (await readNodeRamSnapshot(node)).snap;
  } catch (e) {
    console.error(`[node-ram-guard] could not read RAM snapshot for ${node.name}:`, e instanceof Error ? e.message : e);
  }
  cache.set(node.id, { at: now, snap });
  return snap;
}

export type NodeGuardResult = RamGuardVerdict & { unknown: boolean };

/** Guard verdict for placing a VM of `newVmMB` on `node`. */
export async function nodeRamGuard(node: NodeLike, newVmMB: number): Promise<NodeGuardResult> {
  const snap = await nodeRamSnapshot(node);
  if (!snap) {
    return { ok: false, unknown: true, reason: "live RAM snapshot unavailable", projectedGuaranteedPct: NaN, projectedRealPct: NaN };
  }
  return { ...ramGuardVerdict(snap, newVmMB, ramGuardConfig()), unknown: false };
}

/** Test hook. */
export function _clearNodeRamCache() {
  cache.clear();
}

