/** Split a Proxmox device string (`virtio=AA:…,bridge=vmbr0`) into its parts. */
function parts(value: unknown): string[] {
  return String(value ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

/**
 * Which of the requested keys did NOT take, comparing the config we asked for
 * against the config Proxmox reports.
 *
 * `net0`/`ipconfig0` are compared component-wise: PVE normalises and may ADD
 * fields (`firewall=1`, a `link_down` flag, a `,type=` it filled in). Requiring
 * a byte-exact match would fail a correct apply, and a test that fails on
 * correct behaviour gets deleted. Requiring every component we ASKED FOR to be
 * present is the property that actually matters — in particular that `ip=` is
 * the address the `Server` row holds and not the archive's.
 *
 * Returns human-readable mismatch descriptions; empty means the apply is proven.
 */
export function restoreIdentityMismatches(
  desired: VmIdentityConfig,
  actual: Record<string, unknown> | null | undefined,
): string[] {
  const out: string[] = [];
  if (!actual || typeof actual !== "object") {
    return ["Proxmox returned no config for the restored VM, so nothing could be verified"];
  }

  for (const key of ["cores", "memory", "onboot"] as const) {
    const want = Number(desired[key]);
    const got = Number((actual as Record<string, unknown>)[key]);
    if (!Number.isFinite(got) || got !== want) {
      out.push(`${key}: expected ${want}, VM reports ${String((actual as Record<string, unknown>)[key] ?? "unset")}`);
    }
  }

  for (const key of ["net0", "ipconfig0"] as const) {
    const want = parts(desired[key]);
    const got = new Set(parts((actual as Record<string, unknown>)[key]));
    const missing = want.filter((p) => {
      if (got.has(p)) return false;
      // A NAT server's desired net0 deliberately leaves the MAC unpinned —
      // restoreIdentityConfig's NAT branch returns bare `"virtio,bridge=…"`,
      // with no `=<mac>`, since NAT routing is done by IP/DNAT, not MAC. But
      // Proxmox always reports a REAL device back with whatever MAC it
      // actually assigned (`"virtio=aa:bb:…"`) — a bare `"virtio"` device
      // spec is never what `GET .../config` returns for an existing VM. The
      // exact-token comparison below therefore reported this as a mismatch
      // on every single NAT-server restore, 100% of the time, regardless of
      // any real collision risk — found live 2026-09-11 (a customer's backup
      // restore failed 3 times and left his VM powered off; the actual IP,
      // bridge and disk size all matched exactly). Bare "virtio" only means
      // "some virtio device, MAC not asserted" — satisfied by any actual
      // token that IS a virtio device, with or without a MAC. Every other
      // token (an explicit "virtio=<mac>" for a dedicated IP, "bridge=…",
      // "ip=…", "gw=…") still requires an exact match, unchanged.
      if (p === "virtio") {
        return ![...got].some((g) => g === "virtio" || g.startsWith("virtio="));
      }
      return true;
    });
    if (missing.length > 0) {
      out.push(
        `${key}: expected ${missing.join(", ")}, VM reports "${String(
          (actual as Record<string, unknown>)[key] ?? "unset",
        )}"`,
      );
    }
  }

