// Worker-side application of lib/vm-memory-policy.ts to EXISTING VMs.
import type { PveClient } from "../lib/proxmox";
import { balloonFor, balloonPolicy, guaranteedMB } from "../lib/vm-memory-policy";

type ConfigClient = Pick<PveClient, "get" | "post" | "node">;

/**
 * Bring an EXISTING VM's balloon in line with the policy when its floor is
 * below its RAM. Best-effort (never fails the job it rides on) and only on
 * paths that cold-cycle or start the VM afterwards, so the change takes
 * effect: UNSUSPEND (VM is stopped, applied at next start),
 * ASSIGN_DEDICATED_IP (shutdown + start), BACKUP_RESTORE (config replaced by
 * the archive's). `floor` policy leaves configs alone. A VM already
 * guaranteed its full RAM (balloon 0, unset, or == memory) is not touched.
 */
export async function pinVmMemoryBestEffort(conn: ConfigClient, vmid: number, why: string): Promise<void> {
  const policy = balloonPolicy();
  if (policy === "floor") return;
  try {
    // Default (pending-applied) view: what the VM will boot with.
    const cfg = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
    const mem = Number(cfg?.memory);
    if (!(mem > 0)) return;
    const cur = cfg?.balloon === undefined || cfg?.balloon === "" ? null : Number(cfg.balloon);
    if (guaranteedMB(mem, cur) >= mem) return;
    const want = balloonFor(mem, policy);
    await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, { balloon: want });
    console.log(`[worker] ${why}: vm ${vmid} balloon ${cur ?? "unset"} -> ${want} (memory ${mem}, policy ${policy})`);
  } catch (e) {
    console.error(`[worker] ${why}: could not apply memory policy to vm ${vmid}`, e);
  }
}
