/**
 * Pure planning for scripts/pin-vm-memory.ts: which existing customer VMs
 * need their balloon floor raised to their plan RAM, what that costs each
 * node, and a safe order to do it in. No I/O here so it is unit-tested.
 */
import {
  pinVerdict,
  balloonFor,
  balloonChangeIsLive,
  guaranteedMB,
  pinnedHeadroomMB,
  type BalloonPolicy,
  type NodeRamSnapshot,
  type PinVerdict,
  type RamGuardConfig,
} from "./vm-memory-policy";

export type CandidateVm = {
  vmid: number;
  node: string;
  hostname: string;
  serverId: string;
  /** Proxmox runtime status ("running" | "stopped" ...). */
  status: string;
  memoryMB: number;
  /** Current (running) config balloon, null = unset. */
  balloonMB: number | null;
  /** Pending-applied config balloon (what the next cold start gets), null = unset. */
  pendingBalloonMB: number | null;
  /** Live balloon target right now (MB), when running and the device reports it. */
  liveActualMB: number | null;
  planRamMB: number;
  /** Players online per PlayerSession (leftAt null); null = not a tracked game. */
  playersOnline: number | null;
  /** Config `lock` (backup/migrate/...) — never touch a locked VM. */
  lock: string | null;
};

export type VmPlan = CandidateVm & {
  verdict: PinVerdict;
  /** balloon value to write (only meaningful when verdict.action === "pin"). */
  targetBalloonMB: number;
  /** Applied immediately (pin mode, device stays on) vs waits for a cold stop+start. */
  live: boolean;
  /** Extra guaranteed RAM this VM adds to its node once pinned. */
  addedGuaranteeMB: number;
  /** RAM the guest will grow back by once pinned (running + currently squeezed). */
  regrowMB: number;
};

export function planVm(v: CandidateVm, mode: BalloonPolicy): VmPlan {
  const verdict = pinVerdict({ memoryMB: v.memoryMB, balloonMB: v.balloonMB, pendingBalloonMB: v.pendingBalloonMB, planRamMB: v.planRamMB });
  const target = mode === "floor" ? v.balloonMB ?? v.memoryMB : balloonFor(v.memoryMB, mode);
  const running = v.status === "running";
  const added = verdict.action === "pin" && running ? Math.max(0, v.memoryMB - guaranteedMB(v.memoryMB, v.balloonMB)) : 0;
  const regrow = verdict.action === "pin" && running && v.liveActualMB !== null ? Math.max(0, v.memoryMB - v.liveActualMB) : 0;
  return {
    ...v,
    verdict,
    targetBalloonMB: target,
    live: running && balloonChangeIsLive(v.balloonMB, target),
    addedGuaranteeMB: added,
    regrowMB: regrow,
  };
}

export type NodePlan = {
  node: string;
  snap: NodeRamSnapshot | null;
  vms: VmPlan[];
  /** Guaranteed RAM on the node after every "pin" VM here is pinned. */
  guaranteedAfterMB: number | null;
  /** RAM guests will grow back by right after pinning (pin mode, running). */
  regrowMB: number;
  /** Headroom under the RAM guard now / after. Negative = over. */
  headroomNowMB: number | null;
  headroomAfterMB: number | null;
  /** SAFE: pinning everything here keeps the node within the guard. */
  safe: boolean;
  warning: string | null;
};

export function planNode(node: string, snap: NodeRamSnapshot | null, vms: VmPlan[], cfg: RamGuardConfig): NodePlan {
  const toPin = vms.filter((v) => v.verdict.action === "pin");
  const added = toPin.reduce((s, v) => s + v.addedGuaranteeMB, 0);
  const regrow = toPin.reduce((s, v) => s + v.regrowMB, 0);
  if (!snap) {
    return { node, snap, vms, guaranteedAfterMB: null, regrowMB: regrow, headroomNowMB: null, headroomAfterMB: null, safe: false, warning: "node unreachable — RAM unknown, do not apply" };
  }
  const after: NodeRamSnapshot = { ...snap, guaranteedMB: snap.guaranteedMB + added, usedMB: snap.usedMB + regrow };
  const hNow = pinnedHeadroomMB(snap, cfg);
  const hAfter = pinnedHeadroomMB(after, cfg);
  const safe = hAfter >= 0;
  let warning: string | null = null;
  if (!safe) {
    warning =
      `pinning all ${toPin.length} VM(s) here would put the node ${-hAfter} MB over the RAM guard ` +
      `(guaranteed ${after.guaranteedMB} MB, real used ~${after.usedMB} MB of ${snap.totalMB} MB). ` +
      `Move VMs off this node (VM_MOVE) or pin with --max and watch, before pinning everything.`;
  }
  return { node, snap, vms, guaranteedAfterMB: after.guaranteedMB, regrowMB: regrow, headroomNowMB: hNow, headroomAfterMB: hAfter, safe, warning };
}

/**
 * Safe rollout order: least-loaded nodes first (by real used ratio), and
 * within a node stopped VMs first (no live effect), then running VMs with 0
 * players, then the rest by fewest players, then smallest RAM first.
 * Returns only VMs whose verdict is "pin" and which are not locked.
 */
export function rolloutOrder(nodes: NodePlan[]): VmPlan[] {
  const ratio = (n: NodePlan) => (n.snap && n.snap.totalMB > 0 ? n.snap.usedMB / n.snap.totalMB : Infinity);
  const sortedNodes = [...nodes].sort((a, b) => ratio(a) - ratio(b));
  const out: VmPlan[] = [];
  for (const n of sortedNodes) {
    const vms = n.vms
      .filter((v) => v.verdict.action === "pin" && !v.lock)
      .sort((a, b) => {
        const ra = a.status === "running" ? 1 : 0;
        const rb = b.status === "running" ? 1 : 0;
        if (ra !== rb) return ra - rb;
        const pa = a.playersOnline ?? 0;
        const pb = b.playersOnline ?? 0;
        if (pa !== pb) return pa - pb;
        return a.memoryMB - b.memoryMB;
      });
    out.push(...vms);
  }
  return out;
}

