/**
 * One-time remediation: give EXISTING customer VMs a balloon floor equal to
 * their plan RAM, so Proxmox can no longer squeeze them on a busy node (the
 * 2026-10-01 Valheim case: a 4 GB VM sat at ~1.8 GB on node-4). New VMs get
 * this from the worker already (lib/vm-memory-policy.ts).
 *
 * DRY RUN BY DEFAULT. Reads only: the DB (Server/Node/PlayerSession) and the
 * Proxmox API of every enabled node (status, VM list, each customer VM's
 * current + pending config, live balloon). Prints, per node: real RAM,
 * guaranteed RAM now/after, headroom under the scheduler's RAM guard, every
 * customer VM whose floor is below its plan RAM, and a safe rollout order.
 *
 * --apply writes `balloon` into the VM config via the API. It NEVER stops,
 * starts or reboots anything.
 *   --mode pin (default): balloon = memory. The balloon device stays on, so
 *       Proxmox applies the new minimum at once and pvestatd raises the guest
 *       back to its full RAM on its next pass. No restart needed.
 *       Verify: `qm monitor <vmid>` -> `info balloon` shows actual == max, or
 *       `free -m` in the guest shows ~the plan size.
 *   --mode off: balloon = 0 (device removed). NOT hotpluggable: the change
 *       sits in pending config until a COLD stop + start of the VM
 *       (`qm shutdown <vmid> --timeout 120 && qm start <vmid>`, or Shutdown
 *       then Start in the UI). A reboot from inside the guest does NOT apply
 *       it, because the QEMU process keeps running.
 *
 * Only VMs that are a `Server` row (customer VMs) are ever touched. Platform
 * VMs (mail, Kodely, freemc-host, Soul Pilates ...) are counted in the node
 * RAM totals but never changed. Locked VMs (backup/migrate in progress) are
 * skipped. On a node where pinning everything would break the RAM guard the
 * script refuses to apply there unless --allow-pressure is given.
 *
 * Usage (owner, from /opt/nxeon with its .env):
 *   npx tsx scripts/pin-vm-memory.ts                       # dry run, whole fleet
 *   npx tsx scripts/pin-vm-memory.ts --node node-4         # one node
 *   npx tsx scripts/pin-vm-memory.ts --vmid 123 --apply    # one VM
 *   npx tsx scripts/pin-vm-memory.ts --apply --max 3       # first 3 in rollout order
 *   flags: --mode pin|off  --allow-pressure  --json
 */
import { db } from "../lib/db";
import { pveFor } from "../lib/proxmox";
import { readNodeRamSnapshot } from "../lib/node-ram-guard";
import { ramGuardConfig, type BalloonPolicy } from "../lib/vm-memory-policy";
import { planVm, planNode, rolloutOrder, type CandidateVm, type NodePlan } from "../lib/vm-memory-rollout";

const argv = process.argv.slice(2);
function flag(name: string): boolean {
  return argv.includes(`--${name}`);
}
function opt(name: string): string | undefined {
  const i = argv.findIndex((a) => a === `--${name}` || a.startsWith(`--${name}=`));
  if (i < 0) return undefined;
  const a = argv[i];
  return a.includes("=") ? a.slice(a.indexOf("=") + 1) : argv[i + 1];
}

const APPLY = flag("apply");
const JSON_OUT = flag("json");
const ALLOW_PRESSURE = flag("allow-pressure");
const MODE_RAW = (opt("mode") ?? "pin").toLowerCase();
if (MODE_RAW !== "pin" && MODE_RAW !== "off") {
  console.error(`--mode must be pin or off (got ${MODE_RAW})`);
  process.exit(2);
}
const MODE = MODE_RAW as BalloonPolicy;
const NODE_FILTER = opt("node");
const VMID_FILTER = opt("vmid") !== undefined ? Number(opt("vmid")) : undefined;
const MAX = opt("max") !== undefined ? Math.max(0, Math.trunc(Number(opt("max")))) : Infinity;
if (VMID_FILTER !== undefined && !Number.isInteger(VMID_FILTER)) {
  console.error("--vmid must be an integer");
  process.exit(2);
}
if (!Number.isFinite(MAX) && opt("max") !== undefined) {
  console.error("--max must be a number");
  process.exit(2);
}

const MB = 1024 * 1024;

function n(v: unknown): number | null {
  if (v === undefined || v === null || v === "") return null;
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
}

