  const cfg = ramGuardConfig();
  const nodes = await db.node.findMany({
    where: { enabled: true, ...(NODE_FILTER ? { OR: [{ name: NODE_FILTER }, { pveNode: NODE_FILTER }] } : {}) },
    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
  });
  if (nodes.length === 0) {
    console.error(NODE_FILTER ? `no enabled node named ${NODE_FILTER}` : "no enabled nodes");
    process.exit(1);
  }
  const primary = await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } });

  const servers = await db.server.findMany({
    where: { vmid: { not: null }, status: { notIn: ["DELETING"] }, ...(VMID_FILTER !== undefined ? { vmid: VMID_FILTER } : {}) },
    select: {
      id: true,
      hostname: true,
      vmid: true,
      nodeId: true,
      gamePlanId: true,
      plan: { select: { ramMB: true } },
      gamePlan: { select: { ramMB: true } },
    },
  });
  const online = await db.playerSession.groupBy({
    by: ["serverId"],
    where: { leftAt: null, serverId: { in: servers.map((s) => s.id) } },
    _count: { _all: true },
  });
  const onlineBy = new Map(online.map((o) => [o.serverId, o._count._all]));

