  for (const node of nodes) {
    const mine = servers.filter((s) => (s.nodeId ?? primary?.id) === node.id);
    const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
    let snap = null;
    let listed: { vmid: number; status: string; template?: boolean; name?: string }[] = [];
    try {
      const r = await readNodeRamSnapshot(node);
      snap = r.snap;
      listed = r.vms;
    } catch (e) {
      console.error(`[${node.name}] unreachable: ${e instanceof Error ? e.message : e}`);
