          conn.get(`/nodes/${node.pveNode}/qemu/${s.vmid}/config`, { current: 1 }),
          conn.get(`/nodes/${node.pveNode}/qemu/${s.vmid}/config`),
          vm.status === "running" ? conn.get(`/nodes/${node.pveNode}/qemu/${s.vmid}/status/current`).catch(() => null) : Promise.resolve(null),
        ]);
        const actualBytes = n(live?.ballooninfo?.actual) ?? n(live?.balloon);
        candidates.push({
          vmid: s.vmid!,
          node: node.name,
          hostname: s.hostname,
          serverId: s.id,
          status: vm.status,
          memoryMB: n(current?.memory) ?? 0,
          balloonMB: n(current?.balloon),
          pendingBalloonMB: n(pending?.balloon),
          liveActualMB: actualBytes !== null ? Math.round(actualBytes / MB) : null,
          planRamMB: s.gamePlan?.ramMB ?? s.plan.ramMB,
          playersOnline: s.gamePlanId ? onlineBy.get(s.id) ?? 0 : null,
          lock: typeof current?.lock === "string" ? current.lock : null,
        });
      } catch (e) {
        console.error(`[${node.name}] vm ${s.vmid} (${s.hostname}): config read failed: ${e instanceof Error ? e.message : e}`);
      }
    }
    const missing = snap ? mine.filter((s) => !byVmid.has(s.vmid!)) : [];
    if (missing.length && !JSON_OUT) {
      console.log(`[${node.name}] ${missing.length} Server row(s) point here but the VM is not on this node: ${missing.map((m) => `${m.hostname}/${m.vmid}`).join(", ")}`);
    }
    plans.push(planNode(node.name, snap, candidates.map((c) => planVm(c, MODE)), cfg));
  }

  const order = rolloutOrder(plans);

  if (JSON_OUT) {
    console.log(JSON.stringify({ mode: MODE, guard: cfg, nodes: plans, rollout: order.map((v) => ({ node: v.node, vmid: v.vmid, hostname: v.hostname })) }, null, 2));
  } else {
    console.log(`\nMode: ${MODE} (${MODE === "pin" ? "balloon = memory, applied live, no restart" : "balloon = 0, needs a COLD stop+start per VM"})`);
    console.log(`RAM guard: host reserve ${cfg.hostReserveMB} MB, guaranteed <= ${cfg.maxGuaranteedRatio * 100}% of (total - reserve), real <= ${cfg.maxRealRatio * 100}% of total\n`);
    for (const p of plans) {
      const s = p.snap;
      console.log(`== ${p.node}`);
      if (!s) {
        console.log(`   ${p.warning}`);
        continue;
      }
      console.log(
        `   RAM ${s.totalMB} MB total, ${s.usedMB} MB used (${Math.round((s.usedMB / s.totalMB) * 100)}%), ` +
          `${s.runningVms} running VMs, guaranteed ${s.guaranteedMB} MB now -> ${p.guaranteedAfterMB} MB after, ` +
          `guests regrow ~${p.regrowMB} MB`,
      );
      console.log(`   guard headroom: ${p.headroomNowMB} MB now -> ${p.headroomAfterMB} MB after  ${p.safe ? "SAFE" : "OVER"}`);
      if (p.warning) console.log(`   WARNING: ${p.warning}`);
      for (const v of p.vms) {
        if (v.verdict.action === "ok") continue;
        const players = v.playersOnline === null ? "" : `, ${v.playersOnline} online`;
        const live = v.liveActualMB !== null ? `, live ${v.liveActualMB} MB` : "";
        console.log(
          `   - ${v.vmid} ${v.hostname} [${v.status}${players}] memory ${v.memoryMB} balloon ${v.balloonMB ?? "unset"}${live}, plan ${v.planRamMB}: ` +
            `${v.verdict.action} (${v.verdict.note})${v.lock ? ` LOCKED(${v.lock})` : ""}`,
        );
      }
      const ok = p.vms.filter((v) => v.verdict.action === "ok").length;
      console.log(`   ${ok} customer VM(s) already guaranteed their plan RAM`);
    }
    console.log(`\nRollout order (${order.length} VM(s) to pin):`);
    order.forEach((v, i) => console.log(`  ${i + 1}. ${v.node} ${v.vmid} ${v.hostname} [${v.status}${v.playersOnline === null ? "" : `, ${v.playersOnline} online`}] -> balloon ${v.targetBalloonMB}${v.live ? " (live)" : " (needs cold stop+start)"}`));
  }

  if (!APPLY) {
    if (!JSON_OUT) console.log("\nDRY RUN — nothing changed. Re-run with --apply (and ideally --max N) to write the configs.");
    return;
  }

  const unsafeNodes = new Set(plans.filter((p) => !p.safe).map((p) => p.node));
  const nodeByName = new Map(nodes.map((x) => [x.name, x]));
  let applied = 0;
  const needsColdRestart: string[] = [];
  for (const v of order) {
    if (applied >= MAX) break;
    if (unsafeNodes.has(v.node) && !ALLOW_PRESSURE) {
      console.log(`SKIP ${v.node} ${v.vmid}: node would exceed the RAM guard (use --allow-pressure only after freeing RAM there)`);
      continue;
    }
    const node = nodeByName.get(v.node)!;
    const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
    try {
      await conn.post(`/nodes/${node.pveNode}/qemu/${v.vmid}/config`, { balloon: v.targetBalloonMB });
      const after = await conn.get(`/nodes/${node.pveNode}/qemu/${v.vmid}/config`);
      const got = n(after?.balloon);
      applied += 1;
      console.log(`SET  ${v.node} ${v.vmid} ${v.hostname}: balloon ${v.balloonMB ?? "unset"} -> ${got ?? "unset"}${v.live ? " (live)" : " (pending until cold stop+start)"}`);
      if (!v.live && v.status === "running") needsColdRestart.push(`${v.node}: qm shutdown ${v.vmid} --timeout 120 && qm start ${v.vmid}   # ${v.hostname}`);
      await db.auditLog
        .create({
          data: {
            userId: null,
            action: "ops.vm_memory_pinned",
            category: "server",
            detail: `scripts/pin-vm-memory.ts: ${v.node} vm ${v.vmid} (${v.hostname}, server ${v.serverId}) balloon ${v.balloonMB ?? "unset"} -> ${v.targetBalloonMB}, mode ${MODE}`,
          },
        })
        .catch((e) => console.error(`  audit log write failed: ${e instanceof Error ? e.message : e}`));
    } catch (e) {
      console.error(`FAIL ${v.node} ${v.vmid}: ${e instanceof Error ? e.message : e}`);
    }
  }
  console.log(`\nApplied ${applied} VM(s). Nothing was restarted.`);
  if (needsColdRestart.length) {
    console.log("These need a COLD stop+start before the change takes effect (a guest reboot is not enough). Coordinate with each customer first:");
    for (const l of needsColdRestart) console.log(`  ${l}`);
  }
