    console.log("pin mode: verify after ~1 minute with `qm monitor <vmid>` -> `info balloon` (actual should equal max) or `free -m` in the guest.");
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

