  assert.equal(balloonPolicy({ NXEON_BALLOON_POLICY: "OFF" }), "off");
  assert.equal(balloonPolicy({ NXEON_BALLOON_POLICY: " floor " }), "floor");
  assert.equal(balloonPolicy({ NXEON_BALLOON_POLICY: "50%" }), "pin");
});

test("balloonFor: pin = memory, off = 0, floor = legacy 50%/min 1024", () => {
  assert.equal(balloonFor(4096, "pin"), 4096);
  assert.equal(balloonFor(4096, "off"), 0);
  assert.equal(balloonFor(4096, "floor"), 2048);
  assert.equal(balloonFor(1536, "floor"), 1024);
