  assert.equal(legacyBalloonFloorMB(512), 512);
  assert.deepEqual(memoryConfig(8192, "pin"), { memory: 8192, balloon: 8192 });
  assert.throws(() => balloonFor(0, "pin"));
  assert.throws(() => balloonFor(Number.NaN, "pin"));
