  assert.equal(pinVerdict({ memoryMB: 4096, balloonMB: 2048, planRamMB: 4096 }).action, "pin");
  assert.equal(pinVerdict({ memoryMB: 4096, balloonMB: 0, planRamMB: 4096 }).action, "ok");
  assert.equal(pinVerdict({ memoryMB: 4096, balloonMB: 4096, planRamMB: 4096 }).action, "ok");
  assert.equal(pinVerdict({ memoryMB: 4096, balloonMB: 2048, pendingBalloonMB: 0, planRamMB: 4096 }).action, "pending-restart");
  assert.equal(pinVerdict({ memoryMB: 2048, balloonMB: 0, planRamMB: 4096 }).action, "memory-below-plan");
  // a VM sized above its plan (game plan on a bigger base plan) only needs the plan guaranteed
  assert.equal(pinVerdict({ memoryMB: 8192, balloonMB: 6144, planRamMB: 6144 }).action, "ok");
