  // guaranteed limit 51072 - 30000 = 21072; real limit 57600 - 30000 = 27600
  assert.equal(pinnedHeadroomMB(snap({}), cfg), 21072);
  assert.equal(pinnedHeadroomMB(snap({ usedMB: 56000 }), cfg), 1600);
});

