  assert.equal(off.targetBalloonMB, 0);
  assert.equal(off.live, false);
  const stopped = planVm(vm({ status: "stopped", liveActualMB: null }), "pin");
  assert.equal(stopped.addedGuaranteeMB, 0);
  assert.equal(stopped.regrowMB, 0);
