      vm({ vmid: 21, node: "calm", playersOnline: 0 }),
      vm({ vmid: 22, node: "calm", status: "stopped", liveActualMB: null }),
      vm({ vmid: 23, node: "calm", lock: "backup" }),
      vm({ vmid: 24, node: "calm", balloonMB: 0 }),
      vm({ vmid: 25, node: "calm", playersOnline: null, memoryMB: 2048, planRamMB: 2048, balloonMB: 1024 }),
