import { pinVmMemoryBestEffort } from "../worker/memory-policy";

function fakeConn(config: Record<string, unknown>, opts: { failGet?: boolean } = {}) {
  const posts: Record<string, unknown>[] = [];
  return {
    posts,
    conn: {
      node: "n1",
      get: async () => {
        if (opts.failGet) throw new Error("boom");
        return config;
      },
      post: async (_p: string, body?: Record<string, unknown>) => {
        posts.push(body ?? {});
        return null;
      },
    },
  };
}

test("pinVmMemoryBestEffort: raises a 50% floor to memory under pin (default)", async () => {
  delete process.env.NXEON_BALLOON_POLICY;
  const f = fakeConn({ memory: "4096", balloon: "2048" });
  await pinVmMemoryBestEffort(f.conn, 101, "test");
  assert.deepEqual(f.posts, [{ balloon: 4096 }]);
});

test("pinVmMemoryBestEffort: leaves already-guaranteed VMs alone; floor policy is a no-op; errors are swallowed", async () => {
  for (const cfg of [{ memory: 4096, balloon: 0 }, { memory: 4096 }, { memory: 4096, balloon: 4096 }]) {
    const f = fakeConn(cfg);
    await pinVmMemoryBestEffort(f.conn, 101, "test");
    assert.deepEqual(f.posts, []);
  }
  process.env.NXEON_BALLOON_POLICY = "floor";
  const fl = fakeConn({ memory: 4096, balloon: 2048 });
  await pinVmMemoryBestEffort(fl.conn, 101, "test");
  assert.deepEqual(fl.posts, []);
  process.env.NXEON_BALLOON_POLICY = "off";
  const off = fakeConn({ memory: 4096, balloon: 2048 });
  await pinVmMemoryBestEffort(off.conn, 101, "test");
  assert.deepEqual(off.posts, [{ balloon: 0 }]);
  delete process.env.NXEON_BALLOON_POLICY;
  const bad = fakeConn({}, { failGet: true });
  await pinVmMemoryBestEffort(bad.conn, 101, "test"); // must not throw
});
